INSERT INTO kabinet_profiles (id, periode, nama_kabinet, visi, misi, pengurus_inti, proker_utama, departemen, is_active) VALUES ('2b7318ef-1933-4ac7-859b-5f895a81e718', '2025/2026', 'GATTYA NISCALA', '"Mewujudkan BEM STMIK Tazkia sebagai katalisator yang adaptif, aktif, dan progresif dalam menciptakan ruang kolaborasi yang berasaskan nilai Islami, guna membentuk mahasiswa yang percaya diri, kreatif, dan berdedikasi dalam memberikan kebermanfaatan nyata bagi almamater serta bangsa."', '["Menginisiasi program kerja yang non-boring, kreatif, dan berdampak nyata sebagai wadah eksplorasi mahasiswa yang interaktif dan mempererat solidaritas","Menjadi advokator Transparan yang menjembatani aspirasi mahasiswa ke pihak kampus secata taktis, demi terciptanya kebijakan kampus yang pro-mahasiswa dan suportif.","Memfasilitasi Pengembangan Hard Skill & Soft Skill mahasiswa melalui kolaborasi strategis, guna mencetak prestasi yang kompetitif baik di ranah akademik maupun di industri kreatif.","Membangun internal BEM sebagai Safe Space yang inklusif, kolaboratif dan adaptif terhadap perubahan, sebagai fondasi organisasi yang bertumbuh bersama.","Menumbuhkan ekosistem kampus yang Ethical & Positive Vibes dengan mengintegrasikan nilai-nilai Islami ke dalam perilaku sehari-hari"]'::jsonb, '[{"bg":"#e1e7ff","ig":"-","wa":"+62 878-6368-8998","foto":"","name":"Rahmawati","role":"Ketua BEM","color":"#1b4086","initials":"R"},{"bg":"#ffdbca","ig":"https://www.instagram.com/hei.its_cha/","wa":"+62 858-9373-4378","name":"Anisa Aulia","role":"Wakil Ketua BEM","color":"#f2791e","initials":"A"},{"bg":"#bce9ff","ig":"-","wa":"+62 818-101-882","name":"Abdurrahman Fathi Mubarok","role":"Sekretaris ","color":"#006684","initials":"AF"},{"bg":"#e1e7ff","ig":"https://www.instagram.com/mtiacrnn_/","wa":"+62 896-8752-8449","name":"Mutia Carinna","role":"Sekretaris","color":"#1b4086","initials":"MC"},{"bg":"bg-orange-100","ig":"-","wa":"-","foto":"","name":"Radel Virdiana","role":"-","color":"text-orange-